import { renderWelcome } from '../src/welcome.js';

describe('welcome help menu', () => {
  it('lists the analytics command under Insights', () => {
    const output = renderWelcome({
      packageName: 'mint',
      version: '1.0.0',
      signedIn: true,
    });

    expect(output).toContain('Insights');
    expect(output).toContain('analytics');
    expect(output).toContain('View analytics for your site');
  });
});
